// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/sprints", wrapper.ListSprints)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/sprints", wrapper.CreateSprint)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/sprints/planning/capacity", wrapper.CalculateSprintCapacity)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/sprints/planning/forecast", wrapper.ForecastSprintCompletion)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/api/v1/sprints/{id}", wrapper.DeleteSprint)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/sprints/{id}", wrapper.GetSprint)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/api/v1/sprints/{id}", wrapper.UpdateSprint)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/sprints/{id}/burndown", wrapper.GetSprintBurndown)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/sprints/{id}/close", wrapper.CloseSprint)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/sprints/{id}/metrics", wrapper.GetSprintMetrics)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/sprints/{id}/velocity", wrapper.GetSprintVelocity)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/sprints/{id}/workitems", wrapper.GetSprintWorkItems)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/workitems", wrapper.ListWorkItems)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/workitems", wrapper.CreateWorkItem)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/workitems/search", wrapper.SearchWorkItems)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/api/v1/workitems/{id}", wrapper.DeleteWorkItem)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/workitems/{id}", wrapper.GetWorkItem)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/api/v1/workitems/{id}", wrapper.UpdateWorkItem)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/workitems/{id}/children", wrapper.GetChildWorkItems)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/workitems/{id}/dependencies", wrapper.GetWorkItemDependencies)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/workitems/{id}/dependencies", wrapper.CreateWorkItemDependency)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/api/v1/workitems/{id}/dependencies/{dependency_id}", wrapper.DeleteWorkItemDependency)
	})

	return r
}
